using UnityEngine;
using Newtonsoft.Json;
using System.IO;

public class GameData
{
    public string playerName;
    public int score;
    public float health;
}

public class JsonSavingExample : MonoBehaviour
{
    private string savePath;

    void Awake()
    {
        savePath = Path.Combine(Application.persistentDataPath, "gamedata.json");
    }

    public void SaveGame()
    {
        GameData data = new GameData
        {
            playerName = "PlayerOne",
            score = 1000,
            health = 95.5f
        };

        string json = JsonConvert.SerializeObject(data, Formatting.Indented);
        File.WriteAllText(savePath, json);
        Debug.Log("Game data saved to: " + savePath);
    }

    public void LoadGame()
    {
        if (File.Exists(savePath))
        {
            string json = File.ReadAllText(savePath);
            GameData data = JsonConvert.DeserializeObject<GameData>(json);
            Debug.Log("Game data loaded:");
            Debug.Log("Player Name: " + data.playerName);
            Debug.Log("Score: " + data.score);
            Debug.Log("Health: " + data.health);
        }
        else
        {
            Debug.LogWarning("Save file not found at: " + savePath);
        }
    }
}

using UnityEngine;

public class PlayerAnimatorController : MonoBehaviour
{
    private Animator animator;
    private float moveSpeed;

    void Awake()
    {
        animator = GetComponent<Animator>();
    }

    void Update()
    {
        // --- Bool: Chuyển đổi giữa chạy và đứng yên ---
        bool isMoving = Input.GetKey(KeyCode.W) || Input.GetKey(KeyCode.A) || Input.GetKey(KeyCode.S) || Input.GetKey(KeyCode.D);
        animator.SetBool("IsRunning", isMoving);

        // --- Trigger: Kích hoạt animation tấn công ---
        if (Input.GetKeyDown(KeyCode.Space))
        {
            animator.SetTrigger("Attack");
        }

        // --- Float for Blend Tree: Điều khiển tốc độ di chuyển ---
        // Giả sử bạn có một Blend Tree 1D tên là "MoveSpeed"
        // điều khiển animation đi bộ/chạy dựa trên tốc độ.
        float horizontalInput = Input.GetAxis("Horizontal");
        float verticalInput = Input.GetAxis("Vertical");
        Vector2 inputVector = new Vector2(horizontalInput, verticalInput);
        moveSpeed = inputVector.magnitude;

        animator.SetFloat("MoveSpeed", moveSpeed);
    }
}

using UnityEngine;

public class MovementLimiter : MonoBehaviour
{
    public Vector2 minBounds;
    public Vector2 maxBounds;

    void Update()
    {
        // Lấy vị trí hiện tại
        Vector3 currentPosition = transform.position;

        // Giới hạn tọa độ x và y
        float clampedX = Mathf.Clamp(currentPosition.x, minBounds.x, maxBounds.x);
        float clampedY = Mathf.Clamp(currentPosition.y, minBounds.y, maxBounds.y);

        // Cập nhật lại vị trí của đối tượng
        transform.position = new Vector3(clampedX, clampedY, currentPosition.z);
    }

    // Vẽ vùng giới hạn trong Editor để dễ hình dung
    void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.yellow;
        Vector3 center = new Vector3((minBounds.x + maxBounds.x) / 2, (minBounds.y + maxBounds.y) / 2, 0);
        Vector3 size = new Vector3(maxBounds.x - minBounds.x, maxBounds.y - minBounds.y, 0);
        Gizmos.DrawWireCube(center, size);
    }
}

using UnityEngine;

public class TouchAndMouseInput : MonoBehaviour
{
    public float moveSpeed = 10f;

    void Update()
    {
        Vector3 targetPosition = Vector3.zero;
        bool hasInput = false;

        // Xử lý Touch Input
        if (Input.touchCount > 0)
        {
            Touch touch = Input.GetTouch(0);
            if (touch.phase == TouchPhase.Moved || touch.phase == TouchPhase.Stationary)
            {
                targetPosition = Camera.main.ScreenToWorldPoint(touch.position);
                hasInput = true;
            }
        }
        // Xử lý Mouse Input
        else if (Input.GetMouseButton(0)) // 0 là nút chuột trái
        {
            targetPosition = Camera.main.ScreenToWorldPoint(Input.mousePosition);
            hasInput = true;
        }

        if (hasInput)
        {
            targetPosition.z = transform.position.z; // Giữ nguyên trục Z
            transform.position = Vector3.MoveTowards(transform.position, targetPosition, moveSpeed * Time.deltaTime);
        }
    }
}

using UnityEngine;
using System.Collections;

public class SlowMotionEffect : MonoBehaviour
{
    public float slowMotionFactor = 0.5f;
    public float slowMotionDuration = 2f;

    // Kích hoạt hiệu ứng
    public void TriggerSlowMotion()
    {
        StartCoroutine(DoSlowMotion());
    }

    private IEnumerator DoSlowMotion()
    {
        Time.timeScale = slowMotionFactor;
        Time.fixedDeltaTime = Time.timeScale * 0.02f;

        // Chờ hết thời gian slow motion
        yield return new WaitForSecondsRealtime(slowMotionDuration);

        // Trở về tốc độ bình thường
        Time.timeScale = 1f;
        Time.fixedDeltaTime = 0.02f;
    }

    // Ví dụ cách kích hoạt hiệu ứng khi nhấn phím Q
    void Update()
    {
        if (Input.GetKeyDown(KeyCode.Q))
        {
            TriggerSlowMotion();
        }
    }
}

