using System.Collections;
using UnityEngine;

public class BlinkEffect : MonoBehaviour
{
    private SpriteRenderer spriteRenderer;

    void Awake()
    {
        spriteRenderer = GetComponent<SpriteRenderer>();
    }

    public void StartBlinking(float duration, float blinkInterval)
    {
        StartCoroutine(BlinkCoroutine(duration, blinkInterval));
    }

    private IEnumerator BlinkCoroutine(float duration, float blinkInterval)
    {
        float endTime = Time.time + duration;
        while (Time.time < endTime)
        {
            spriteRenderer.enabled = !spriteRenderer.enabled;
            yield return new WaitForSeconds(blinkInterval);
        }
        spriteRenderer.enabled = true; // Ensure sprite is visible at the end
    }
}

using UnityEngine;
using UnityEngine.UI;

public class StaminaController : MonoBehaviour
{
    public float maxStamina = 100f;
    private float currentStamina;

    public float staminaDrainRate = 20f; // Stamina mất mỗi giây khi chạy
    public float staminaRegenRate = 10f; // Stamina hồi mỗi giây khi đứng yên

    public Slider staminaBar; // Tham chiếu đến UI Slider

    private bool isSprinting = false;

    void Start()
    {
        currentStamina = maxStamina;
        if (staminaBar != null) staminaBar.maxValue = maxStamina;
    }

    void Update()
    {
        // Kiểm tra input chạy (ví dụ: giữ phím Shift)
        isSprinting = Input.GetKey(KeyCode.LeftShift) && currentStamina > 0;

        if (isSprinting)
        {
            currentStamina -= staminaDrainRate * Time.deltaTime;
        }
        else if (currentStamina < maxStamina)
        {
            currentStamina += staminaRegenRate * Time.deltaTime;
        }

        currentStamina = Mathf.Clamp(currentStamina, 0, maxStamina);

        if (staminaBar != null)
        {
            staminaBar.value = currentStamina;
        }
    }

    public bool CanSprint()
    {
        return currentStamina > 0;
    }
}

using UnityEngine;

public class PickupAndThrow : MonoBehaviour
{
    public Transform holdPoint; // Điểm giữ vật thể trước mặt camera/player
    public float throwForce = 20f;
    private GameObject heldObject;
    private Rigidbody heldObjectRb;

    void Update()
    {
        if (Input.GetKeyDown(KeyCode.E))
        {
            if (heldObject == null)
            {
                // Thử nhặt vật thể
                RaycastHit hit;
                if (Physics.Raycast(transform.position, transform.forward, out hit, 5f))
                {
                    if (hit.collider.GetComponent<Rigidbody>()) // Kiểm tra có Rigidbody không
                    {
                        PickupObject(hit.collider.gameObject);
                    }
                }
            }
            else
            {
                // Thả vật thể
                DropObject();
            }
        }

        if (heldObject != null && Input.GetMouseButtonDown(0)) // Nút chuột trái để ném
        {
            ThrowObject();
        }
    }

    void PickupObject(GameObject obj)
    {
        heldObject = obj;
        heldObjectRb = obj.GetComponent<Rigidbody>();
        heldObjectRb.useGravity = false;
        heldObjectRb.drag = 10;
        heldObjectRb.constraints = RigidbodyConstraints.FreezeRotation;
        heldObject.transform.parent = holdPoint;
        heldObject.transform.position = holdPoint.position;
    }

    void DropObject()
    {
        heldObjectRb.useGravity = true;
        heldObjectRb.drag = 1;
        heldObjectRb.constraints = RigidbodyConstraints.None;
        heldObject.transform.parent = null;
        heldObject = null;
    }

    void ThrowObject()
    {
        Rigidbody rbToThrow = heldObjectRb;
        DropObject(); // Thả ra trước khi ném
        rbToThrow.AddForce(transform.forward * throwForce, ForceMode.Impulse);
    }
}

