using UnityEngine;
using System.Collections;

public class AIPatrol : MonoBehaviour
{
    public Transform[] waypoints;
    public float moveSpeed = 3f;
    private int currentWaypointIndex = 0;

    void Update()
    {
        if (waypoints.Length == 0) return;

        // Di chuyển tới waypoint hiện tại
        transform.position = Vector3.MoveTowards(transform.position, waypoints[currentWaypointIndex].position, moveSpeed * Time.deltaTime);

        // Kiểm tra nếu đã đến gần waypoint
        if (Vector3.Distance(transform.position, waypoints[currentWaypointIndex].position) < 0.1f)
        {
            // Chuyển sang waypoint tiếp theo
            currentWaypointIndex = (currentWaypointIndex + 1) % waypoints.Length;
        }
    }

    // Vẽ các đường nối waypoints trong Editor để dễ hình dung
    void OnDrawGizmos()
    {
        if (waypoints == null || waypoints.Length < 2) return;
        for (int i = 0; i < waypoints.Length; i++)
        {
            Gizmos.color = Color.cyan;
            Gizmos.DrawWireSphere(waypoints[i].position, 0.3f);
            if (i > 0)
            {
                Gizmos.DrawLine(waypoints[i-1].position, waypoints[i].position);
            }
        }
        Gizmos.DrawLine(waypoints[waypoints.Length-1].position, waypoints[0].position);
    }
}

using UnityEngine;

public class SimpleFSM : MonoBehaviour
{
    public enum AIState { Idle, Patrol, Chase, Attack }

    public AIState currentState;
    public Transform player;
    public float chaseRange = 10f;
    public float attackRange = 2f;

    void Start()
    {
        currentState = AIState.Idle;
    }

    void Update()
    {
        float distanceToPlayer = Vector3.Distance(transform.position, player.position);

        switch (currentState)
        {
            case AIState.Idle:
                // Nếu người chơi ở trong tầm, bắt đầu đuổi theo
                if (distanceToPlayer < chaseRange)
                {
                    currentState = AIState.Chase;
                }
                // Có thể thêm hành vi 'nhìn xung quanh' ở đây
                break;

            case AIState.Patrol:
                // Thực hiện logic đi tuần
                // Nếu thấy người chơi, chuyển sang Chase
                if (distanceToPlayer < chaseRange)
                {
                    currentState = AIState.Chase;
                }
                break;

            case AIState.Chase:
                // Đuổi theo người chơi
                transform.position = Vector3.MoveTowards(transform.position, player.position, 3f * Time.deltaTime);

                // Nếu người chơi ở trong tầm tấn công, chuyển sang Attack
                if (distanceToPlayer < attackRange)
                {
                    currentState = AIState.Attack;
                }
                // Nếu người chơi chạy quá xa, quay lại Idle hoặc Patrol
                else if (distanceToPlayer > chaseRange * 1.5f)
                {
                    currentState = AIState.Idle;
                }
                break;

            case AIState.Attack:
                // Thực hiện logic tấn công (ví dụ: chạy animation, gây sát thương)
                Debug.Log("Attacking player!");

                // Nếu người chơi thoát khỏi tầm tấn công, quay lại Chase
                if (distanceToPlayer > attackRange)
                {
                    currentState = AIState.Chase;
                }
                break;
        }
    }
}

using UnityEngine;
using System.Collections;

[System.Serializable]
public class Wave
{
    public string name;
    public GameObject enemyPrefab;
    public int count;
    public float spawnRate;
}

public class EnemyWaveSpawner : MonoBehaviour
{
    public Wave[] waves;
    public Transform[] spawnPoints;
    public float timeBetweenWaves = 5f;

    private int currentWaveIndex = 0;
    private int enemiesRemaining;

    void Start()
    {
        StartCoroutine(SpawnAllWaves());
    }

    IEnumerator SpawnAllWaves()
    {
        while (currentWaveIndex < waves.Length)
        {
            yield return new WaitForSeconds(timeBetweenWaves);
            yield return StartCoroutine(SpawnWave(waves[currentWaveIndex]));
            currentWaveIndex++;
        }
        Debug.Log("All waves completed!");
    }

    IEnumerator SpawnWave(Wave wave)
    {
        Debug.Log("Spawning Wave: " + wave.name);
        enemiesRemaining = wave.count;

        for (int i = 0; i < wave.count; i++)
        {
            SpawnEnemy(wave.enemyPrefab);
            yield return new WaitForSeconds(1f / wave.spawnRate);
        }

        // Chờ đến khi tất cả kẻ địch trong wave bị tiêu diệt
        while (enemiesRemaining > 0)
        {
            yield return null; // Chờ đến frame tiếp theo
        }
    }

    void SpawnEnemy(GameObject enemyPrefab)
    {
        Transform randomSpawnPoint = spawnPoints[Random.Range(0, spawnPoints.Length)];
        GameObject enemyInstance = Instantiate(enemyPrefab, randomSpawnPoint.position, randomSpawnPoint.rotation);

        // Giả sử kẻ địch có một script HealthSystem hoặc tương tự
        // để thông báo khi nó chết. Cần phải có cơ chế này.
        // Ví dụ: enemyInstance.GetComponent<EnemyHealth>().OnDeath += OnEnemyDeath;
    }

    // Hàm này được gọi khi một kẻ địch bị tiêu diệt
    public void OnEnemyDeath()
    {
        enemiesRemaining--;
    }
}

