using UnityEngine;

public class AIChase : MonoBehaviour
{
    public Transform playerTransform;
    public float moveSpeed = 4f;
    public float detectionRange = 10f;
    public float stopChasingRange = 15f;

    private bool isChasing = false;

    void Update()
    {
        if (playerTransform == null)
        {
            // Cố gắng tìm người chơi nếu chưa có tham chiếu
            GameObject player = GameObject.FindGameObjectWithTag("Player");
            if (player != null) playerTransform = player.transform;
            else return; // Không tìm thấy người chơi
        }

        float distanceToPlayer = Vector3.Distance(transform.position, playerTransform.position);

        if (isChasing)
        {
            // Nếu đang đuổi, tiếp tục di chuyển tới người chơi
            transform.position = Vector3.MoveTowards(transform.position, playerTransform.position, moveSpeed * Time.deltaTime);
            // Nhìn về phía người chơi
            transform.LookAt(playerTransform);

            // Nếu người chơi ra khỏi phạm vi dừng, ngừng đuổi
            if (distanceToPlayer > stopChasingRange)
            {
                isChasing = false;
            }
        }
        else
        {
            // Nếu người chơi vào trong phạm vi phát hiện, bắt đầu đuổi
            if (distanceToPlayer < detectionRange)
            {
                isChasing = true;
            }
        }
    }

    // Vẽ phạm vi trong Editor
    void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.yellow;
        Gizmos.DrawWireSphere(transform.position, detectionRange);
        Gizmos.color = Color.red;
        Gizmos.DrawWireSphere(transform.position, stopChasingRange);
    }
}

using UnityEngine;

public class AIRangedAttack : MonoBehaviour
{
    public Transform playerTransform;
    public GameObject projectilePrefab;
    public Transform firePoint;
    public float attackRange = 15f;
    public float fireRate = 1f; // Số lần bắn mỗi giây
    private float nextFireTime = 0f;

    void Update()
    {
        if (playerTransform == null) return;

        float distanceToPlayer = Vector3.Distance(transform.position, playerTransform.position);

        if (distanceToPlayer <= attackRange)
        {
            // Nhìn về phía người chơi
            transform.LookAt(playerTransform.position);

            // Kiểm tra nếu đã đến lúc bắn
            if (Time.time >= nextFireTime)
            {
                Shoot();
                nextFireTime = Time.time + 1f / fireRate;
            }
        }
    }

    void Shoot()
    {
        if (projectilePrefab != null && firePoint != null)
        {
            Instantiate(projectilePrefab, firePoint.position, firePoint.rotation);
        }
    }

    void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.red;
        Gizmos.DrawWireSphere(transform.position, attackRange);
    }
}

using UnityEngine;

// Gắn script này vào Player
public class ObjectPusher : MonoBehaviour
{
    public float pushForce = 5.0f;

    // Hàm này được gọi khi CharacterController va chạm với một đối tượng khác
    void OnControllerColliderHit(ControllerColliderHit hit)
    {
        Rigidbody body = hit.collider.attachedRigidbody;

        // Kiểm tra xem đối tượng có Rigidbody hay không và nó không phải là kinematic
        if (body == null || body.isKinematic)
        {
            return;
        }

        // Không đẩy các vật thể ở bên trên chúng ta
        if (hit.moveDirection.y < -0.3f)
        {
            return;
        }

        // Tính toán hướng đẩy
        Vector3 pushDirection = new Vector3(hit.moveDirection.x, 0, hit.moveDirection.z);

        // Tác động lực lên Rigidbody của vật thể
        body.velocity = pushDirection * pushForce;
    }
}

