// Hướng dẫn sử dụng:
// 1. Gắn script này vào một GameObject rỗng trong Scene, ví dụ [LODManager].
// 2. Kéo Player (hoặc camera chính) vào ô 'target'.
// 3. Trong Scene, tìm tất cả các GameObject có component 'LOD Group' và kéo chúng vào danh sách 'lodGroups'.

using UnityEngine;
using System.Collections.Generic;

public class LODManager : MonoBehaviour
{
    public Transform target; // Thường là Player hoặc Camera
    public List<LODGroup> lodGroups; // Danh sách các LOD Group cần quản lý
    public float checkInterval = 0.5f; // Thời gian giữa mỗi lần kiểm tra khoảng cách

    private float timer;

    void Start()
    {
        if (target == null)
        {
            target = Camera.main.transform;
            Debug.LogWarning("LODManager: Target not set, defaulting to Main Camera.");
        }
    }

    void Update()
    {
        timer += Time.deltaTime;
        if (timer >= checkInterval)
        {
            timer = 0f;
            UpdateAllLODs();
        }
    }

    void UpdateAllLODs()
    {
        if (target == null || lodGroups == null) return;

        foreach (LODGroup group in lodGroups)
        {
            if (group != null)
            {
                // ForceRecalculateBounds() cập nhật lại vị trí và kích thước của group
                // Hữu ích nếu các đối tượng trong group có thể di chuyển
                group.ForceRecalculateBounds();
                // Unity sẽ tự động chọn LOD phù hợp dựa trên khoảng cách từ 'target'
            }
        }
    }
}

using UnityEngine;
using UnityEngine.UI;

public class MapMarker : MonoBehaviour
{
    public Transform target; // Mục tiêu cần đánh dấu
    public Image markerImage; // Image UI của marker
    public Camera uiCamera; // Camera của Canvas (nếu dùng Screen Space - Camera)
    private RectTransform canvasRect;

    void Start()
    {
        canvasRect = markerImage.canvas.GetComponent<RectTransform>();
    }

    void LateUpdate()
    {
        if (target == null || markerImage == null) {
            if (markerImage != null) markerImage.enabled = false;
            return;
        }

        Vector3 targetScreenPos = Camera.main.WorldToScreenPoint(target.position);

        // Kiểm tra xem mục tiêu có ở phía trước camera không
        bool isTargetVisible = targetScreenPos.z > 0 && 
                               targetScreenPos.x > 0 && targetScreenPos.x < Screen.width && 
                               targetScreenPos.y > 0 && targetScreenPos.y < Screen.height;

        if (isTargetVisible)
        {
            markerImage.enabled = true;
            markerImage.rectTransform.position = targetScreenPos;
        }
        else // Nếu mục tiêu ở ngoài màn hình
        {
            markerImage.enabled = true;
            // Đảo ngược vị trí nếu mục tiêu ở sau lưng
            if (targetScreenPos.z < 0) {
                targetScreenPos *= -1;
            }

            // Tính toán vị trí ghim vào cạnh màn hình
            Vector3 center = new Vector3(Screen.width / 2, Screen.height / 2, 0);
            targetScreenPos -= center;

            float angle = Mathf.Atan2(targetScreenPos.y, targetScreenPos.x);
            angle -= 90 * Mathf.Deg2Rad;
            float cos = Mathf.Cos(angle);
            float sin = -Mathf.Sin(angle);

            targetScreenPos = center + new Vector3(sin * 150, cos * 150, 0);

            float m = cos / sin;
            Vector3 screenBounds = center * 0.9f;

            if (cos > 0) {
                targetScreenPos = new Vector3(screenBounds.y / m, screenBounds.y, 0);
            } else {
                targetScreenPos = new Vector3(-screenBounds.y / m, -screenBounds.y, 0);
            }

            if (targetScreenPos.x > screenBounds.x) {
                targetScreenPos = new Vector3(screenBounds.x, screenBounds.x * m, 0);
            } else if (targetScreenPos.x < -screenBounds.x) {
                targetScreenPos = new Vector3(-screenBounds.x, -screenBounds.x * m, 0);
            }

            markerImage.rectTransform.position = center + targetScreenPos;
        }
    }
}

using UnityEngine;

public class LadderClimb : MonoBehaviour
{
    private float verticalInput;
    public float climbSpeed = 3f;
    private bool isClimbing;
    private bool onLadder;

    private Rigidbody2D rb;

    void Start()
    {
        rb = GetComponent<Rigidbody2D>();
    }

    void Update()
    {
        verticalInput = Input.GetAxis("Vertical");

        if (onLadder && Mathf.Abs(verticalInput) > 0f)
        {
            isClimbing = true;
        }
    }

    void FixedUpdate()
    {
        if (isClimbing)
        {
            rb.gravityScale = 0f; // Tắt trọng lực khi leo
            rb.velocity = new Vector2(rb.velocity.x, verticalInput * climbSpeed);
        }
        else
        {
            rb.gravityScale = 3f; // Bật lại trọng lực (thay bằng giá trị mặc định của bạn)
        }
    }

    private void OnTriggerEnter2D(Collider2D collision)
    {
        if (collision.CompareTag("Ladder"))
        {
            onLadder = true;
        }
    }

    private void OnTriggerExit2D(Collider2D collision)
    {
        if (collision.CompareTag("Ladder"))
        {
            onLadder = false;
            isClimbing = false;
        }
    }
}

