using UnityEngine;
using UnityEngine.UI;
using System.Collections;

public class AnimatedHealthBar : MonoBehaviour
{
    public Slider mainHealthSlider;      // Thanh máu chính, hiển thị máu hiện tại
    public Slider delayedHealthSlider; // Thanh máu phụ, chạy theo sau thanh chính
    public float delaySpeed = 2f;      // Tốc độ của thanh máu phụ

    public void SetMaxHealth(int health)
    {
        mainHealthSlider.maxValue = health;
        mainHealthSlider.value = health;
        delayedHealthSlider.maxValue = health;
        delayedHealthSlider.value = health;
    }

    public void SetHealth(int health)
    {
        mainHealthSlider.value = health;
        StartCoroutine(UpdateDelayedSlider(health));
    }

    private IEnumerator UpdateDelayedSlider(int newHealth)
    {
        // Chờ một chút trước khi thanh phụ bắt đầu di chuyển
        yield return new WaitForSeconds(0.5f);

        float timer = 0f;
        float startValue = delayedHealthSlider.value;

        while (timer < 1f)
        {
            timer += Time.deltaTime * delaySpeed;
            delayedHealthSlider.value = Mathf.Lerp(startValue, newHealth, timer);
            yield return null;
        }

        delayedHealthSlider.value = newHealth;
    }
}

using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SceneManagement;
using System.Collections;

public class ScreenFader : MonoBehaviour
{
    public static ScreenFader Instance;
    public Image fadeImage;
    public float fadeSpeed = 1.5f;

    void Awake()
    {
        if (Instance == null) {
            Instance = this;
            DontDestroyOnLoad(gameObject);
        } else {
            Destroy(gameObject);
        }
    }

    public void FadeToScene(string sceneName)
    {
        StartCoroutine(FadeOutAndLoad(sceneName));
    }

    IEnumerator FadeOutAndLoad(string sceneName)
    {
        yield return StartCoroutine(Fade(1f)); // Fade Out
        SceneManager.LoadScene(sceneName);
        yield return StartCoroutine(Fade(0f)); // Fade In
    }

    IEnumerator Fade(float targetAlpha)
    {
        Color currentColor = fadeImage.color;
        float startAlpha = currentColor.a;
        float timer = 0f;

        while (timer < 1f)
        {
            timer += Time.deltaTime * fadeSpeed;
            currentColor.a = Mathf.Lerp(startAlpha, targetAlpha, timer);
            fadeImage.color = currentColor;
            yield return null;
        }

        currentColor.a = targetAlpha;
        fadeImage.color = currentColor;
    }
}

using UnityEngine;
using System.Collections;

public class AIFieldOfView : MonoBehaviour
{
    public float viewRadius = 10f;
    [Range(0, 360)]
    public float viewAngle = 90f;

    public LayerMask targetMask;    // Layer của Player
    public LayerMask obstacleMask;  // Layer của các vật cản (tường, cột,...)

    [HideInInspector]
    public Transform visibleTarget;

    void Update()
    {
        FindVisibleTargets();
    }

    void FindVisibleTargets()
    {
        visibleTarget = null;
        Collider[] targetsInViewRadius = Physics.OverlapSphere(transform.position, viewRadius, targetMask);

        for (int i = 0; i < targetsInViewRadius.Length; i++)
        {
            Transform target = targetsInViewRadius[i].transform;
            Vector3 dirToTarget = (target.position - transform.position).normalized;

            // Kiểm tra xem mục tiêu có nằm trong góc nhìn không
            if (Vector3.Angle(transform.forward, dirToTarget) < viewAngle / 2)
            {
                float dstToTarget = Vector3.Distance(transform.position, target.position);

                // Kiểm tra xem có vật cản nào giữa AI và mục tiêu không
                if (!Physics.Raycast(transform.position, dirToTarget, dstToTarget, obstacleMask))
                {
                    visibleTarget = target; // Nhìn thấy mục tiêu
                    Debug.Log("Player spotted!");
                    return;
                }
            }
        }
    }

    public Vector3 DirFromAngle(float angleInDegrees, bool angleIsGlobal)
    {
        if (!angleIsGlobal)
        {
            angleInDegrees += transform.eulerAngles.y;
        }
        return new Vector3(Mathf.Sin(angleInDegrees * Mathf.Deg2Rad), 0, Mathf.Cos(angleInDegrees * Mathf.Deg2Rad));
    }
}

